     1→import { Navigate } from "react-router-dom";
     2→import { useAppStore } from "@/stores/app-store";
     3→import { getTabUrl, useTabStore, selectActiveTab } from "@/stores/tab-store";
     4→
     5→/**
     6→ * Home redirect component - redirects based on app state.
     7→ * - First-time users are redirected to /onboarding
     8→ * - Returning users are redirected to the active tab's current URL
     9→ * - Fallback to /workspace if no active tab
    10→ */
    11→export function HomeRedirect() {
    12→  const { onboardingCompleted } = useAppStore();
    13→  const activeTab = useTabStore(selectActiveTab);
    14→
    15→  if (!onboardingCompleted) {
    16→    return <Navigate to="/onboarding" replace />;
    17→  }
    18→
    19→  // Restore the active tab's current URL if available
    20→  const activeUrl = activeTab ? getTabUrl(activeTab) : null;
    21→
    22→  return <Navigate to={activeUrl || "/workspace"} replace />;
    23→}
